#!/usr/bin/env node
/**
 * Generates the docs reference pages from package.json and friends.
 *
 * Inputs:
 *   package.json          contributes.commands / submenus / menus / configuration
 *   package.nls.json      resolves %placeholder% titles and submenu labels
 *   resources/**\/*.y*ml   pinned third-party versions
 *
 * Outputs (each with a DO NOT EDIT header):
 *   docs/book/src/reference/commands.md
 *   docs/book/src/reference/settings.md
 *   docs/book/src/reference/pinned-versions.md
 *
 * Usage:
 *   node scripts/generate-docs-reference.js          write the files
 *   node scripts/generate-docs-reference.js --check  fail if the files are stale
 */

"use strict";

const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const OUT_DIR = path.join(ROOT, "docs", "book", "src", "reference");

const read = (p) => fs.readFileSync(path.join(ROOT, p), "utf8");
const readJson = (p) => JSON.parse(read(p));

const {
    contributes,
    loc,
    splitTop,
    stripOuterParens,
    normaliseBoolean,
    submenuById,
    menus,
    walk: walkMenus,
} = require("./lib/menu-graph");

const pkg = readJson("package.json");

const HEADER = (script) =>
    `<!--\n  DO NOT EDIT. Generated by scripts/${script} from package.json.\n  Run: node scripts/${script}\n-->\n\n`;

/** command id -> array of { node, breadcrumb, flags } for one menu mode. */
const buildPaths = (simplified) => walkMenus(simplified).commandPaths;

// ---------------------------------------------------------------------------
// palette
// ---------------------------------------------------------------------------

/**
 * A commandPalette entry hides its command when the `when` clause can never be
 * true. This repo uses both the documented `false` and the idiomatic `never`
 * (an undefined context key, so falsy). Any other clause is a real condition:
 * the command is in the palette, but only when it holds.
 *
 * Returns { hidden:Set, conditional:Map<commandId, whenClause> }.
 */
function buildPaletteVisibility() {
    const NEVER = new Set(["false", "never"]);
    const hidden = new Set();
    const conditional = new Map();
    for (const entry of menus.commandPalette || []) {
        const when = String(entry.when).trim();
        if (NEVER.has(when)) hidden.add(entry.command);
        else if (entry.when) conditional.set(entry.command, entry.when);
    }
    return { hidden, conditional };
}

// ---------------------------------------------------------------------------
// page: commands
// ---------------------------------------------------------------------------

const NODE_LABEL = {
    cluster: "AKS cluster node",
    subscription: "Subscription node",
    fleet: "Fleet node",
    "k8s-cluster": "Kubernetes explorer cluster node",
    azure: "Azure (Cloud Explorer root)",
    other: "Other",
    any: "Any",
};

function renderPath(p) {
    const root = NODE_LABEL[p.node] || p.node;
    return [root, ...p.breadcrumb].join(" > ");
}

const code = (s) => `\`${s}\``;

/**
 * How a gating condition is phrased for a reader, in match order.
 * The first matching rule wins; the last is the fallback.
 */
const CONDITION_RULES = [
    { match: /^config\./, render: (c) => code(c.replace(/^config\./, "")) },
    { match: /^workspaceFolderCount/, render: () => "an open workspace folder" },
    { match: /resourceExtname/, render: () => "a YAML file in the active editor" },
    { match: /.*/, render: code },
];

function renderCondition(condition) {
    const { key, negated } = normaliseBoolean(condition);
    const rule = CONDITION_RULES.find((r) => r.match.test(key));
    return (negated ? "not " : "") + rule.render(key);
}

const friendlyFlag = renderCondition;

/** Renders a raw `when` clause into prose conditions. */
function describeWhen(when) {
    return splitTop(when, "&&")
        .map((c) => renderCondition(stripOuterParens(c).trim()))
        .join(", ");
}

function commandsPage() {
    const simplifiedPaths = buildPaths(true);
    const classicPaths = buildPaths(false);
    const { hidden: hiddenFromPalette, conditional } = buildPaletteVisibility();

    const rows = contributes.commands.map((cmd) => {
        const title = loc(cmd.title);
        const category = cmd.category ? loc(cmd.category) : "";
        const sPaths = simplifiedPaths.get(cmd.command) || [];
        const cPaths = classicPaths.get(cmd.command) || [];
        const flags = [...new Set([...sPaths, ...cPaths].flatMap((p) => p.flags))];
        return {
            id: cmd.command,
            title,
            // VS Code renders "category: title" in the palette
            full: category ? `${category}: ${title}` : title,
            palette: !hiddenFromPalette.has(cmd.command),
            paletteWhen: conditional.get(cmd.command) || null,
            simplified: sPaths.map(renderPath),
            classic: cPaths.map(renderPath),
            flags,
        };
    });

    const cell = (list) => (list.length ? [...new Set(list)].join("<br>") : "\u2014");

    let md = HEADER("generate-docs-reference.js");
    md += "# Commands\n\n";
    md += `Every command the extension contributes, with where it appears in the tree-view menus.\n\n`;
    md += `The menu layout depends on the \`aks.simplifiedMenuStructure\` setting, which defaults to \`true\`.\n`;
    md += `The **Default menu** column reflects that default; **Classic menu** applies when the setting is \`false\`.\n`;
    md += `A dash means the command has no entry in that menu and is reachable only from the Command Palette.\n\n`;

    md += `## Command Palette\n\n`;
    const paletteRows = [...rows].filter((r) => r.palette).sort((a, b) => a.full.localeCompare(b.full));
    const hiddenRows = rows.filter((r) => !r.palette);
    md += `${paletteRows.length} of ${rows.length} commands are available from the Command Palette (\`Ctrl+Shift+P\` / \`Cmd+Shift+P\`).\n\n`;
    md += "| Title | Command ID | Shown when |\n|---|---|---|\n";
    for (const r of paletteRows) {
        md += `| ${r.full} | \`${r.id}\` | ${r.paletteWhen ? describeWhen(r.paletteWhen) : "always"} |\n`;
    }
    if (hiddenRows.length) {
        md += `\nHidden from the palette (invoked from a menu or another command): `;
        md += hiddenRows.map((r) => `\`${r.id}\``).join(", ") + ".\n";
    }

    md += `\n## Menu placement\n\n`;
    md += "| Title | Command ID | Default menu | Classic menu | Requires |\n|---|---|---|---|---|\n";
    for (const r of [...rows].sort((a, b) => a.id.localeCompare(b.id))) {
        const requires = r.flags.length ? r.flags.map(friendlyFlag).join(", ") : "\u2014";
        md += `| ${r.title} | \`${r.id}\` | ${cell(r.simplified)} | ${cell(r.classic)} | ${requires} |\n`;
    }

    return { md, rows, simplifiedPaths, classicPaths };
}

// ---------------------------------------------------------------------------
// page: settings
// ---------------------------------------------------------------------------

function settingsPage() {
    const props = contributes.configuration.properties;
    let md = HEADER("generate-docs-reference.js");
    md += "# Settings\n\n";
    md += `Configure these in **Settings** (\`Ctrl+,\` / \`Cmd+,\`) or in \`settings.json\`.\n\n`;
    md += "| Setting | Type | Default | Description |\n|---|---|---|---|\n";
    for (const key of Object.keys(props).sort()) {
        const p = props[key];
        const type = Array.isArray(p.type) ? p.type.join(" \\| ") : p.type || "\u2014";
        const def = "default" in p ? "`" + JSON.stringify(p.default) + "`" : "\u2014";
        const desc = (p.markdownDescription || p.description || "\u2014").replace(/\n+/g, " ").trim();
        md += `| \`${key}\` | ${type} | ${def} | ${desc} |\n`;
    }
    return md;
}

// ---------------------------------------------------------------------------
// page: pinned versions
// ---------------------------------------------------------------------------

function walk(dir, out = []) {
    for (const e of fs.readdirSync(path.join(ROOT, dir), { withFileTypes: true })) {
        const rel = path.join(dir, e.name);
        if (e.isDirectory()) walk(rel, out);
        else out.push(rel);
    }
    return out;
}

function pinnedVersionsPage() {
    const files = walk("resources").filter((f) => /\.ya?ml$/.test(f));
    // key "owner/repo|version" -> { action, version, sha, files:Set }
    const actions = new Map();

    for (const f of files) {
        read(f)
            .split("\n")
            .forEach((line) => {
                const m = /^\s*(?:-\s*)?uses:\s*([\w.-]+\/[\w.-]+)@([\w.-]+)\s*(?:#\s*(\S+))?/.exec(line);
                if (!m) return;
                const [, action, ref, comment] = m;
                // SHA pins carry the readable tag in a trailing comment
                const isSha = /^[0-9a-f]{40}$/.test(ref);
                const version = isSha ? comment || ref : ref;
                const key = `${action}|${version}`;
                if (!actions.has(key)) actions.set(key, { action, version, isSha, files: new Set() });
                actions.get(key).files.add(f);
            });
    }

    // every "<tool>.releaseTag" setting, so a new tool appears without a code change
    const props = contributes.configuration.properties;
    const tools = Object.keys(props)
        .filter((k) => /\.releaseTag$/i.test(k))
        .sort();

    let md = HEADER("generate-docs-reference.js");
    md += "# Pinned versions\n\n";
    md += "Third-party versions the extension pins.\n\n";

    md += "## Tools\n\n";
    md += "Each is overridable in settings.\n\n";
    md += "| Setting | Pinned version |\n|---|---|\n";
    for (const k of tools) md += `| \`${k}\` | \`${props[k].default}\` |\n`;

    md += "\n## GitHub Actions in generated workflows\n\n";
    md += "Actions pinned to a commit SHA are shown with the tag from their trailing comment.\n\n";
    md += "| Action | Version | Pin | Template |\n|---|---|---|---|\n";
    const sorted = [...actions.values()].sort(
        (a, b) => a.action.localeCompare(b.action) || a.version.localeCompare(b.version),
    );
    for (const a of sorted) {
        const where = [...a.files]
            .sort()
            .map((f) => `\`${f}\``)
            .join("<br>");
        md += `| \`${a.action}\` | \`${a.version}\` | ${a.isSha ? "SHA" : "tag"} | ${where} |\n`;
    }

    return { md, actions: sorted };
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------

function main() {
    const check = process.argv.includes("--check");
    const { md: commandsMd, rows, simplifiedPaths, classicPaths } = commandsPage();
    const { md: pinnedMd, actions } = pinnedVersionsPage();
    const outputs = {
        "commands.md": commandsMd,
        "settings.md": settingsPage(),
        "pinned-versions.md": pinnedMd,
    };

    fs.mkdirSync(OUT_DIR, { recursive: true });
    let stale = 0;
    for (const [name, content] of Object.entries(outputs)) {
        const file = path.join(OUT_DIR, name);
        const existing = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : null;
        if (check) {
            if (existing !== content) {
                console.error(`[stale] docs/book/src/reference/${name}`);
                stale++;
            }
        } else if (existing !== content) {
            fs.writeFileSync(file, content);
            console.log(`[write] docs/book/src/reference/${name}`);
        } else {
            console.log(`[same]  docs/book/src/reference/${name}`);
        }
    }

    if (check) {
        if (stale) {
            console.error(`\n${stale} generated file(s) out of date. Run: node scripts/generate-docs-reference.js`);
            process.exit(1);
        }
        console.log("generated reference is up to date");
        return;
    }

    // findings the menu walk surfaces for free
    const referenced = new Set();
    for (const bucket of Object.keys(menus)) {
        for (const e of menus[bucket]) if (e.submenu) referenced.add(e.submenu);
    }
    const deadSubmenus = [...submenuById.keys()].filter((id) => !referenced.has(id));
    const noMenu = rows.filter((r) => !r.simplified.length && !r.classic.length);
    const paletteOnlyAndNoMenu = noMenu.filter((r) => !r.palette);

    const byTitle = new Map();
    for (const r of rows.filter((r) => r.palette)) {
        if (!byTitle.has(r.full)) byTitle.set(r.full, []);
        byTitle.get(r.full).push(r.id);
    }
    const dupes = [...byTitle.entries()].filter(([, ids]) => ids.length > 1);

    const doublePrefixed = rows.filter((r) => {
        const cmd = contributes.commands.find((c) => c.command === r.id);
        if (!cmd || !cmd.category) return false;
        const cat = loc(cmd.category);
        return loc(cmd.title).toLowerCase().startsWith(cat.toLowerCase());
    });

    console.log(`\n--- menu walk findings ---`);
    console.log(
        `commands: ${rows.length}, in default menu: ${simplifiedPaths.size}, in classic menu: ${classicPaths.size}`,
    );
    if (deadSubmenus.length) console.log(`dead submenus (declared, never referenced): ${deadSubmenus.join(", ")}`);
    if (paletteOnlyAndNoMenu.length)
        console.log(`unreachable (no menu, hidden from palette): ${paletteOnlyAndNoMenu.map((r) => r.id).join(", ")}`);
    for (const [title, ids] of dupes)
        console.log(`duplicate palette title ${JSON.stringify(title)}: ${ids.join(", ")}`);
    for (const r of doublePrefixed)
        console.log(`title repeats its category, palette shows ${JSON.stringify(r.full)}: ${r.id}`);
    const orphanNode = rows.filter((r) => [...r.simplified, ...r.classic].some((p) => p.startsWith("Other")));
    if (orphanNode.length) console.log(`unresolved menu node: ${orphanNode.map((r) => r.id).join(", ")}`);

    // same action pinned to different versions across templates
    const byAction = new Map();
    for (const a of actions) {
        if (!byAction.has(a.action)) byAction.set(a.action, []);
        byAction.get(a.action).push(a);
    }
    for (const [action, uses] of byAction) {
        if (uses.length > 1) console.log(`version skew ${action}: ${uses.map((u) => u.version).join(" vs ")}`);
    }
}

main();
